// ── PLAYER SHIP SPRITE ────────────────────────────────────────────────────────
const SHIP_B64 = "";
const shipSprite = new Image();
shipSprite.src = "data:image/png;base64," + SHIP_B64;

// Nozzle offsets from image center (512,512) in image pixels
// shuttle-2.png pixel-analysed:
//   LEFT pod:   abs=(441,772) → offset=(-71,260), aperture=79px
//   RIGHT pod:  abs=(577,775) → offset=(+65,263), aperture=81px
//   CENTER:     abs=(510,804) → offset=(−2, 292), aperture=52px
const NOZZLES = [
  { dx:-71, dy:260, aper:79, type:"pod"    },
  { dx: 65, dy:263, aper:81, type:"pod"    },
  { dx: -2, dy:292, aper:52, type:"center" },
];

const POD_PAL = [
  null,
  { core:"#fff0cc", inner:"#ff6600", outer:"#aa1500", glow:"rgba(255,80,5,0.35)",   glowR:2.0 },
  { core:"#ffffff", inner:"#ffcc33", outer:"#ee5500", glow:"rgba(255,170,30,0.30)", glowR:2.2 },
  { core:"#ffffff", inner:"#99ddff", outer:"#1155ee", glow:"rgba(50,130,255,0.30)", glowR:2.4 },
  { core:"#ffffff", inner:"#ccf5ff", outer:"#44aaff", glow:"rgba(100,210,255,0.28)",glowR:2.5 },
];
const CENTER_BURN_PAL = { core:"#ffffff", inner:"#ccf5ff", outer:"#55bbff", glow:"rgba(120,220,255,0.25)", glowR:2.8 };
const POD_LEN    = [0, 1.3, 2.0, 2.8, 3.2];
const CENTER_LEN = [0, 0,   0,   0,   3.8];
const FLAME_WID  = [0, 0.72, 0.78, 0.84, 0.86];

let engineSparks = [];
let engineTick = 0;

function drawEngineFlame(c, lx, ly, aper, pal, lenMult, widMult, isCenter, tt) {
  const flicker = 1 + Math.sin(tt*0.39)*0.045 + Math.sin(tt*0.71+1.3)*0.024;
  const len = aper * lenMult * flicker;
  const wid = aper * widMult;
  const glowR = aper * pal.glowR;

  // Outer bloom
  const g = c.createRadialGradient(lx, ly, 0, lx, ly+len*0.28, glowR);
  g.addColorStop(0, pal.glow); g.addColorStop(1, "transparent");
  c.fillStyle=g; c.beginPath();
  c.ellipse(lx, ly+len*0.24, glowR*0.52, glowR, 0, 0, Math.PI*2); c.fill();

  // Flame body
  const grad = c.createLinearGradient(lx, ly, lx, ly+len);
  grad.addColorStop(0.00, pal.core); grad.addColorStop(0.10, pal.inner);
  grad.addColorStop(0.60, pal.outer); grad.addColorStop(1.00, "transparent");
  c.fillStyle=grad; c.beginPath();
  c.moveTo(lx-wid*0.5, ly);
  c.bezierCurveTo(lx-wid*0.60, ly+len*0.35, lx-wid*0.18, ly+len*0.82, lx, ly+len);
  c.bezierCurveTo(lx+wid*0.18, ly+len*0.82, lx+wid*0.60, ly+len*0.35, lx+wid*0.5, ly);
  c.closePath(); c.fill();

  // Inner core
  const cLen = len*0.44;
  const cg = c.createLinearGradient(lx, ly, lx, ly+cLen);
  cg.addColorStop(0,"#ffffff"); cg.addColorStop(0.45,pal.core+"cc"); cg.addColorStop(1,"transparent");
  c.fillStyle=cg; c.beginPath();
  c.ellipse(lx, ly+cLen*0.35, wid*0.13, cLen*0.52, 0, 0, Math.PI*2); c.fill();

  // Afterburner extras (center only)
  if (isCenter) {
    const dmid = ly+len*0.32;
    const dr = c.createRadialGradient(lx,dmid,0,lx,dmid,wid*0.7);
    dr.addColorStop(0,"rgba(200,245,255,0.38)"); dr.addColorStop(1,"transparent");
    c.fillStyle=dr; c.beginPath();
    c.ellipse(lx,dmid,wid*0.28,wid*0.44,0,0,Math.PI*2); c.fill();
    const dmid2=ly+len*0.58;
    const dr2=c.createRadialGradient(lx,dmid2,0,lx,dmid2,wid*0.55);
    dr2.addColorStop(0,"rgba(180,235,255,0.24)"); dr2.addColorStop(1,"transparent");
    c.fillStyle=dr2; c.beginPath();
    c.ellipse(lx,dmid2,wid*0.22,wid*0.35,0,0,Math.PI*2); c.fill();
    if (Math.random()<0.28) engineSparks.push({
      x:lx+rand(-wid*0.25,wid*0.25), y:ly+rand(0,len*0.3),
      vx:rand(-0.7,0.7), vy:rand(0.8,2.2), life:rand(12,26), maxLife:26, r:rand(1,2.4)
    });
  }
}

function drawPlayerShip(c, cx, cy, angle, jmag, tt) {
  // Determine engine level from thrust magnitude
  const lvl = jmag < 0.05 ? 0 : jmag < 0.35 ? 1 : jmag < 0.65 ? 2 : jmag < 0.88 ? 3 : 4;

  const drawSize = 56; // ship draw size in canvas pixels
  const sc = drawSize / 1024;

  c.save();
  c.translate(cx, cy);
  c.rotate(angle);

  // Flames behind sprite
  if (lvl > 0) {
    NOZZLES.forEach(n => {
      const lx = n.dx * sc, ly = n.dy * sc, aper = n.aper * sc;
      if (n.type === "pod") {
        drawEngineFlame(c, lx, ly, aper, POD_PAL[lvl], POD_LEN[lvl], FLAME_WID[lvl], false, tt);
      } else if (n.type === "center" && lvl === 4) {
        drawEngineFlame(c, lx, ly, aper, CENTER_BURN_PAL, CENTER_LEN[4], FLAME_WID[4]*0.9, true, tt);
      }
    });
  }

  // Sparks (local space)
  if (lvl < 4) engineSparks.length = 0;
  for (let i=engineSparks.length-1; i>=0; i--) {
    const s=engineSparks[i], a=s.life/s.maxLife;
    c.fillStyle=`rgba(180,235,255,${a*0.72})`;
    c.beginPath(); c.arc(s.x,s.y,s.r*a,0,Math.PI*2); c.fill();
    s.x+=s.vx; s.y+=s.vy; s.life--;
    if(s.life<=0) engineSparks.splice(i,1);
  }

  // Ship sprite
  if (shipSprite.complete && shipSprite.naturalWidth) {
    c.drawImage(shipSprite, -drawSize/2, -drawSize/2, drawSize, drawSize);
  } else {
    // Fallback while image loads
    c.beginPath(); c.moveTo(0,-14); c.lineTo(8,9); c.lineTo(0,4); c.lineTo(-8,9); c.closePath();
    c.fillStyle="#0d1520"; c.fill(); c.strokeStyle="#4a9eff"; c.lineWidth=1.5; c.stroke();
  }

  c.restore();
}


